TERMS={'FF3 spell Mini':'MSG_MAGIC_NAME_06','FF3 spell Toad':'MSG_MAGIC_NAME_05',
 'FF3 item Nepto Eye':'MSG_KEY_NAME_02','FF3 item Eureka Key':'MSG_KEY_NAME_06','FF3 item Syrcus Key':'MSG_KEY_NAME_07',
 'FF3 item Antidote':'MSG_ITEM_NAME_03','FF3 item Horn of Ice':'MSG_KEY_NAME_03'}
def main():
 sys.path.insert(0,str(ROOT.parent/'tools'));import dump_map_objects as archive
 bundles=list(Path(archive.aa_path('ff3')).glob('message_assets_*.bundle'));assert len(bundles)==1
 _,assets=archive.load_texts(str(bundles[0]));rows={key:dict(zip(LOCALES,values)) for key,values in ROWS.items()}
 assert all(len(values)==12 and values[0]==key and all(values) for key,values in ROWS.items())
 for key,message in TERMS.items():
  rows[key]={}
  for locale in LOCALES:
   texts=assets['system_'+locale];assert len(texts)==1
   terms=dict(line.rstrip('\r\n').split('\t',1) for line in texts[0].splitlines() if '\t' in line)
   rows[key][locale]=re.sub(r'<[^>]*>','',terms[message]).strip();assert rows[key][locale] and '<' not in rows[key][locale]
 original=P.read_text(encoding='utf-8');catalog=json.loads(original)
 additions={key:value for key,value in rows.items() if key not in catalog}
 if '--check' in sys.argv:assert not additions,'Missing FFIII puzzle translations'
 if additions:
  insertion=json.dumps(additions,ensure_ascii=False,indent=2)[2:-2]
  P.write_text(original[:original.rfind('}')].rstrip()+',\n'+insertion+'\n}\n',encoding='utf-8');catalog.update(additions)
 for key,value in rows.items():assert catalog[key]==value,('FFIII puzzle translation differs',key)
 (ROOT/'build_check/ff3_puzzle_locales.json').write_text(json.dumps(dict(instructions=len(ROWS),terms=TERMS,locales=LOCALES,
  bundle=bundles[0].name,bundle_sha256=hashlib.sha256(bundles[0].read_bytes()).hexdigest()),indent=2)+'\n',encoding='utf-8')
 print('FFIII puzzles:',len(ROWS),'instructions and',len(TERMS),'exact official terms in twelve languages;',len(additions),'added')
if __name__=='__main__':main()
